<?php
$items = $items ?? [];
$farms = $farms ?? [];
$warehouses = $warehouses ?? [];
$requests = $requests ?? [];
$fulfillmentLines = $fulfillment_lines ?? [];
$error = $error ?? null;
$success = $success ?? null;
$csrf = htmlspecialchars(csrf_token(), ENT_QUOTES, 'UTF-8');
$groupedFulfillment = [];
foreach ($fulfillmentLines as $line) {
    $groupedFulfillment[$line['request_id']][] = $line;
}
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Solicitudes internas | CampoSur</title><link rel="stylesheet" href="/assets/css/app.css"></head><body class="admin-page"><main class="admin-shell"><?php require dirname(__DIR__) . '/Views/partials/module-navigation.php'; ?><header class="admin-header"><div><p class="eyebrow">Bodega</p><h1>Solicitudes internas</h1><p class="setup-copy">Pide materiales, revisa las solicitudes y controla su entrega.</p></div><a class="secondary-link" href="?module=warehouses">Volver a bodegas</a></header><?php if ($error): ?><div class="setup-error"><?= htmlspecialchars($error, ENT_QUOTES, 'UTF-8') ?></div><?php endif; ?><?php if ($success): ?><div class="setup-success"><?= htmlspecialchars($success, ENT_QUOTES, 'UTF-8') ?></div><?php endif; ?><section class="admin-columns"><article class="admin-panel"><header class="panel-header"><h2>Nueva solicitud</h2></header><form method="post" class="admin-form"><input type="hidden" name="csrf" value="<?= $csrf ?>"><input type="hidden" name="action" value="create_request"><label>Fecha<input type="date" name="requested_on" value="<?= htmlspecialchars(date('Y-m-d'), ENT_QUOTES, 'UTF-8') ?>" required></label><label>Fundo<select name="farm_id"><option value="">Sin fundo</option><?php foreach ($farms as $farm): ?><option value="<?= (int) $farm['id'] ?>"><?= htmlspecialchars($farm['name'], ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select></label><label>Artículo<select name="item_id" required><?php foreach ($items as $item): ?><option value="<?= (int) $item['id'] ?>"><?= htmlspecialchars($item['name'] . ' · ' . $item['sku'], ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select></label><label>Cantidad<input type="number" name="quantity" min="0.001" step="0.001" value="1" required></label><label>Notas<input name="notes" maxlength="255"></label><button class="primary-button" type="submit">Crear solicitud</button></form></article><article class="admin-panel"><header class="panel-header"><h2>Solicitudes registradas</h2></header><table class="data-table"><thead><tr><th>Fecha</th><th>Solicitante</th><th>Fundo</th><th>Estado</th><th>Artículos</th><th></th></tr></thead><tbody><?php foreach ($requests as $request): ?><tr><td><?= htmlspecialchars($request['requested_on'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($request['requester'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($request['farm_name'] ?: '—', ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($request['status'], ENT_QUOTES, 'UTF-8') ?></td><td><?= (int) $request['items_count'] ?></td><td><?php if ($request['status'] === 'REQUESTED'): ?><form method="post"><input type="hidden" name="csrf" value="<?= $csrf ?>"><input type="hidden" name="action" value="approve_request"><input type="hidden" name="request_id" value="<?= (int) $request['id'] ?>"><button class="button-link" type="submit">Aprobar</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></article></section><section class="admin-columns"><article class="admin-panel"><header class="panel-header"><h2>Atender solicitudes aprobadas</h2></header><?php if ($groupedFulfillment): ?><?php foreach ($groupedFulfillment as $requestId => $lines): ?><form method="post" class="admin-form"><input type="hidden" name="csrf" value="<?= $csrf ?>"><input type="hidden" name="action" value="fulfill_request"><input type="hidden" name="request_id" value="<?= (int) $requestId ?>"><label>Bodega de salida<select name="warehouse_id" required><?php foreach ($warehouses as $warehouse): ?><option value="<?= (int) $warehouse['id'] ?>"><?= htmlspecialchars($warehouse['name'], ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select></label><table class="data-table"><thead><tr><th>Artículo</th><th>Saldo</th><th>Atender</th></tr></thead><tbody><?php foreach ($lines as $line): ?><tr><td><?= htmlspecialchars($line['item_name'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars((string) ((float) $line['quantity'] - (float) $line['fulfilled_quantity']), ENT_QUOTES, 'UTF-8') ?></td><td><input type="number" name="items[<?= (int) $line['request_item_id'] ?>]" min="0" step="0.001" value="0"></td></tr><?php endforeach; ?></tbody></table><button class="primary-button" type="submit">Registrar atención</button></form><?php endforeach; ?><?php else: ?><p class="setup-copy">No hay solicitudes aprobadas pendientes de atención.</p><?php endif; ?></article></section></main></body></html>
